package dndcharacter

import (
	"math/rand"
	"time"
)

type Character struct {
	Strength     int
	Dexterity    int
	Constitution int
	Intelligence int
	Wisdom       int
	Charisma     int
	Hitpoints    int
}

var rng = rand.New(rand.NewSource(time.Now().UnixNano()))

// Modifier calculates the ability modifier for a given ability score.
// The modifier is (score - 10) / 2, rounded down (floor).
func Modifier(score int) int {
	diff := score - 10
	if diff < 0 {
		// Go integer division truncates toward zero, so adjust for
		// negative odd values to round down instead.
		return (diff - 1) / 2
	}
	return diff / 2
}

// Ability uses randomness to generate the score for an ability.
// It rolls four 6-sided dice and returns the sum of the largest three.
func Ability() int {
	sum := 0
	min := 7 // higher than any possible die roll
	for i := 0; i < 4; i++ {
		roll := rng.Intn(6) + 1
		sum += roll
		if roll < min {
			min = roll
		}
	}
	return sum - min
}

// GenerateCharacter creates a new Character with random scores for abilities.
// Hitpoints start at 10 plus the constitution modifier.
func GenerateCharacter() Character {
	character := Character{
		Strength:     Ability(),
		Dexterity:    Ability(),
		Constitution: Ability(),
		Intelligence: Ability(),
		Wisdom:       Ability(),
		Charisma:     Ability(),
	}
	character.Hitpoints = 10 + Modifier(character.Constitution)
	return character
}
